$ErrorActionPreference='Stop'
if($env:OS -ne 'Windows_NT'){throw 'WINDOWS_POWERSHELL_REQUIRED'}
$python=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
'LASU_TIKAI_PASREIZEJO_CASH_SHOP_KATALOGU; NAV_INSTALACIJAS_VAI_PARSTARTESANAS'
$text=($python | ssh -T root@192.168.56.101 python3 - | Out-String)
if($LASTEXITCODE -ne 0){throw 'CASHSHOP291_READ_FAILED; ATSUTI_REDZAMO_IZVADI'}
$report=$text | ConvertFrom-Json
if($report.status -ne 'READ_ONLY_COMPLETE'){throw 'CASHSHOP291_REPORT_INCOMPLETE'}
$bytes=[Convert]::FromBase64String($report.zip_b64)
if($bytes.Length -ne $report.zip_bytes -or $bytes.Length -gt 4MB){throw 'CASHSHOP291_ZIP_SIZE_DIFFERS'}
$hash=[Security.Cryptography.SHA256]::Create()
try{$actual=([BitConverter]::ToString($hash.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose()}
if($actual -ne $report.zip_sha256){throw 'CASHSHOP291_ZIP_HASH_DIFFERS'}
$folder=Join-Path $env:USERPROFILE 'Downloads'
$zip=Join-Path $folder ('CashShop291-Catalogue-'+(Get-Date -Format yyyyMMdd-HHmmss)+'.zip')
[IO.File]::WriteAllBytes($zip,$bytes)
'KATALOGA_SADALAS='+$report.catalogue_pages+'; NOSAUKUMU_SADALAS='+$report.label_pages
'ZIP='+$zip
'ATSUTI_SO_ZIP; SPELE_SERVERIS_UN_SQL_NAV_MAINITI'
